head.script:
// Configure how to derive "Social Media" consent:
//   true  = tie Social Media to HubSpot's Advertisement/Targeting category
//   false = tie Social Media to HubSpot's Functionality category
var SOCIAL_MEDIA_FROM_ADS = true;

// HubSpot listener queue
window._hsp = window._hsp || [];

// Read HubSpot consent cookie for initial state (covers first page load)
function readHubSpotConsentFromCookie() {
  // HubSpot cookie stores category prefs, e.g. "__hs_cookie_cat_pref=1:true_2:false_3:true"
  var m = document.cookie.match(/(?:^|;)\s*__hs_cookie_cat_pref=([^;]+)/);
  if (!m) return null;
  var bits = decodeURIComponent(m[1]).split('_');
  var flags = {};
  bits.forEach(function (p) {
    var kv = p.split(':');
    if (kv.length === 2) flags[kv[0]] = (kv[1] === 'true');
  });
  // HubSpot category indices: 1=analytics, 2=advertisement/targeting, 3=functionality
  return {
    categories: {
      analytics: !!flags['1'],
      advertisement: !!flags['2'],
      functionality: !!flags['3']
    }
  };
}

// Map HubSpot consent -> Segment consent object with your category IDs
function hubspotToSegmentConsent(consent) {
  var c = (consent && consent.categories) || {};
  var socialMedia = SOCIAL_MEDIA_FROM_ADS ? !!c.advertisement : !!c.functionality;

  return {
    // Your Segment categories
    categoryPreferences: {
      C0001: true,               // Strictly Necessary (always on; not user-toggleable)
      C0002: !!c.analytics,      // Performance
      C0003: !!c.functionality,  // Functional
      C0004: !!c.advertisement,  // Targeting
      C0005: socialMedia         // Social Media (derived as configured above)
    },
    provider: "hubspot",
    consentMethod: "banner",
    gpc: !!(navigator && navigator.globalPrivacyControl)
  };
}

// Store latest Segment-style consent globally for middleware to read
function updateSegmentConsent(consent) {
  window.__segmentConsent = hubspotToSegmentConsent(consent);
  window.__segmentConsentUpdatedAt = new Date().toISOString();
}

// Bootstrap from cookie (so first events have a value)
var initial = readHubSpotConsentFromCookie();
if (initial) updateSegmentConsent(initial);

// Listen for HubSpot banner changes (fires on initial set and updates)
window._hsp.push(['addPrivacyConsentListener', function (consent) {
  updateSegmentConsent(consent);
}]);

!function () {
  var analytics = window.analytics = window.analytics || []; if (!analytics.initialize)
    if (analytics.invoked) window.console && console.error && console.error("Segment snippet included twice."); else {
      analytics.invoked = !0; analytics.methods = ["trackSubmit", "trackClick", "trackLink", "trackForm", "pageview", "identify",
        "reset", "group", "track", "ready", "alias", "debug", "page", "once", "off", "on", "addSourceMiddleware",
        "addIntegrationMiddleware", "setAnonymousId", "addDestinationMiddleware"];
      analytics.factory = function (t) { return function () { var e = Array.prototype.slice.call(arguments); e.unshift(t); analytics.push(e); return analytics } };
      for (var t = 0; t < analytics.methods.length; t++) { var e = analytics.methods[t]; analytics[e] = analytics.factory(e) }
      analytics.load = function (key, options) {
        var n = document.createElement("script"); n.async = !0;
        n.src = "https://cdn.segment.com/analytics.js/v1/" + key + "/analytics.min.js";
        var a = document.getElementsByTagName("script")[0]; a.parentNode.insertBefore(n, a); analytics._loadOptions = options
      };
      analytics._writeKey = "Aap2161ZVNxQsUJcAo4slb0BdL18MCqk";
      analytics.load("Aap2161ZVNxQsUJcAo4slb0BdL18MCqk");
      analytics.page();
    }
}();

// Register source middleware immediately (the stub will queue this until analytics.js loads)
if (window.analytics && typeof window.analytics.addSourceMiddleware === 'function') {
  window.analytics.addSourceMiddleware(function ({ payload, next }) {
    var obj = payload.obj || {};
    var ctx = obj.context = obj.context || {};

    if (window.__segmentConsent) {
      ctx.consent = Object.assign({}, window.__segmentConsent, {
        consentTimestamp: window.__segmentConsentUpdatedAt || new Date().toISOString()
      });
    } else {
      // If no banner decision yet, you can choose to send only "Strictly Necessary" explicitly:
      ctx.consent = {
        categoryPreferences: { C0001: true, C0002: false, C0003: false, C0004: false, C0005: false },
        provider: "hubspot",
        consentMethod: "banner:unknown",
        gpc: !!(navigator && navigator.globalPrivacyControl),
        consentTimestamp: new Date().toISOString()
      };
    }

    payload.obj = obj;
    next(payload);
  });
}

// Example calls (leave commented out if you already call these elsewhere)
// analytics.page();
// analytics.track('Button Clicked', { id: 'subscribe' });

window.free_account_type = "";
window.is_hermes = "" === "True" ? true : false;
window.is_freemium = "" === "True" ? true : false;
window.is_developer = "" === "True" ? true : false;

